/**
 * Indexable landing pages for the state versions of an exam family
 * (real estate, life and health, property and casualty): one page per state
 * at `<family landing>/<state-name>`, e.g.
 * /real-estate-practice-test/california. The page is built from the state's
 * ExamConfig and the official facts in lib/stateExamFacts.json (generated by
 * tools/build_state_exam_facts.py from the state's sources file).
 */
import { EXAM_VARIANTS, ExamConfig, getExamById } from "./exams";
import facts from "./stateExamFacts.json";

export type StateExamFacts = { accessed: string | null; rows: { label: string; value: string; url?: string }[] };

export const STATE_FAMILIES = ["realestate", "insurance", "pnc"] as const;
export type StateFamily = (typeof STATE_FAMILIES)[number];

/** What people call each family's exam in a search: "California real estate exam". */
export const FAMILY_TERMS: Record<StateFamily, { exam: string; title: string; licence: string }> = {
  realestate: { exam: "real estate exam", title: "Real Estate Practice Exam", licence: "real estate license" },
  insurance: { exam: "life and health insurance exam", title: "Life & Health Insurance Practice Exam", licence: "life and health insurance license" },
  pnc: { exam: "property and casualty insurance exam", title: "Property & Casualty Practice Exam", licence: "property and casualty insurance license" },
};

const stateSlug = (name: string) => name.toLowerCase().replace(/[^a-z]+/g, "-");

export function stateVariants(family: StateFamily): ExamConfig[] {
  return EXAM_VARIANTS.filter((e) => e.variantOf === family && e.jurisdiction).sort((a, b) =>
    a.jurisdiction!.name.localeCompare(b.jurisdiction!.name)
  );
}

/** "/real-estate-practice-test/california" */
export function stateLandingPath(variant: ExamConfig): string {
  const family = getExamById(variant.variantOf!)!;
  return `${family.landingPath}/${stateSlug(variant.jurisdiction!.name)}`;
}

export function stateVariantBySlug(family: StateFamily, slug: string): ExamConfig | undefined {
  return stateVariants(family).find((e) => stateSlug(e.jurisdiction!.name) === slug);
}

export function stateLandingParams(family: StateFamily): { state: string }[] {
  return stateVariants(family).map((e) => ({ state: stateSlug(e.jurisdiction!.name) }));
}

export function stateExamFacts(variantId: string): StateExamFacts | undefined {
  return (facts as Record<string, StateExamFacts>)[variantId];
}

/** Every state landing on the site, for the sitemap and llms.txt. */
export function allStateLandings(): { variant: ExamConfig; path: string }[] {
  return STATE_FAMILIES.flatMap((f) => stateVariants(f).map((variant) => ({ variant, path: stateLandingPath(variant) })));
}
